    const k = [r.cadastro.id, r.cadastro.codigo_parada, r.cadastro.linha, r.cadastro.sentido].join('|');
    if (vistos.has(k)) { duplicados++; return; }
    vistos.add(k);
    validos.push(r.cadastro);
  });
  return { validos, invalidos, duplicados };
}

