// Camada de I/O usada dentro dos nós Code do n8n (arquivos, logs, env).
// Requer: NODE_FUNCTION_ALLOW_BUILTIN=fs,path,crypto e
//         N8N_BLOCK_ENV_ACCESS_IN_NODE=false (ver README).
